\begin{aligned}
\widetilde T_{\mu\nu}
&=-2\frac{1}{\sqrt{-\widetilde g}}
\frac{\delta S_{\mathrm M}}{\delta\widetilde g^{\mu\nu}}\\
&=-2\frac{1}{\sqrt{-\widetilde g}}
\frac{\partial g^{\alpha\beta}}{\partial\widetilde g^{\mu\nu}}
\frac{\delta S_{\mathrm M}}{\delta g^{\alpha\beta}}\\
&=-2(16\pi\widetilde G f)^{-1}
\frac{1}{\sqrt{-g}}\,
\delta^\alpha_\mu\delta^\beta_\nu
\frac{\delta S_{\mathrm M}}{\delta g^{\alpha\beta}}\\
&=(16\pi\widetilde G f)^{-1}T_{\mu\nu}.
\end{aligned}
\tag{4.137}
